mapper.select:
select * from yh_audit_check


	and
	audit_type = #{auditType,jdbcType=INTEGER}


	and
	audit_status = #{auditStatus,jdbcType=INTEGER}


	AND
	(
		audit_title like CONCAT('%',#{auditTitle},'%' )
	)


	and audit_date between #{entryTime} and #{entryTime1}


order by audit_date desc LIMIT  #{page},#{limit}

select count(*) from yh_audit_check


	and
	audit_type = #{auditType,jdbcType=INTEGER}


	and
	audit_status = #{auditStatus,jdbcType=INTEGER}


	AND
	(
		audit_title like CONCAT('%',#{auditTitle},'%' )
	)


	and audit_date between #{entryTime} and #{entryTime1}


order by audit_date desc
